CREATE TABLE "Retailer" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "name" TEXT NOT NULL, CONSTRAINT "Retailer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Region" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "code" TEXT NOT NULL, CONSTRAINT "Region_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Region_code_key" ON "Region"("code");
CREATE TABLE "RetailStore" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "retailerId" UUID NOT NULL, "regionId" UUID NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "RetailStore_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExternalProduct" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "retailerId" UUID NOT NULL, "externalId" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "ExternalProduct_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "ExternalProduct_retailerId_externalId_key" ON "ExternalProduct"("retailerId","externalId");
CREATE TABLE "ProductMatch" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "productId" UUID NOT NULL, "externalProductId" UUID NOT NULL, "confidence" DECIMAL(5,4) NOT NULL, CONSTRAINT "ProductMatch_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "ProductMatch_productId_externalProductId_key" ON "ProductMatch"("productId","externalProductId");
CREATE TABLE "PriceObservation" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "productId" UUID NOT NULL, "storeId" UUID NOT NULL, "price" DECIMAL(10,2) NOT NULL, "observedAt" TIMESTAMP(3) NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "PriceObservation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PriceSnapshot" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "productId" UUID NOT NULL, "regionId" UUID NOT NULL, "price" DECIMAL(10,2) NOT NULL, "confidence" DECIMAL(5,4) NOT NULL, "observedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PriceSnapshot_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "PriceSnapshot_productId_regionId_key" ON "PriceSnapshot"("productId","regionId");
ALTER TABLE "RetailStore" ADD CONSTRAINT "RetailStore_retailerId_fkey" FOREIGN KEY ("retailerId") REFERENCES "Retailer"("id"); ALTER TABLE "RetailStore" ADD CONSTRAINT "RetailStore_regionId_fkey" FOREIGN KEY ("regionId") REFERENCES "Region"("id"); ALTER TABLE "ExternalProduct" ADD CONSTRAINT "ExternalProduct_retailerId_fkey" FOREIGN KEY ("retailerId") REFERENCES "Retailer"("id"); ALTER TABLE "ProductMatch" ADD CONSTRAINT "ProductMatch_externalProductId_fkey" FOREIGN KEY ("externalProductId") REFERENCES "ExternalProduct"("id") ON DELETE CASCADE; ALTER TABLE "PriceObservation" ADD CONSTRAINT "PriceObservation_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "RetailStore"("id") ON DELETE CASCADE; ALTER TABLE "PriceSnapshot" ADD CONSTRAINT "PriceSnapshot_regionId_fkey" FOREIGN KEY ("regionId") REFERENCES "Region"("id");
